add_action( 'woocommerce_shop_loop_item_title', 'perfectpixel_subcategory_name_in_loop', 5 );

function perfectpixel_subcategory_name_in_loop() {
	$parent = (int) '{{brand_parent_category_id}}';
	if ( ! $parent ) {
		return;
	}
	$names = array();
	foreach ( (array) get_the_terms( get_the_ID(), 'product_cat' ) as $term ) {
		if ( $term && ! is_wp_error( $term ) && term_is_ancestor_of( $parent, $term, 'product_cat' ) ) {
			$names[] = 'yes' === '{{brand_as_link}}'
				? '<a href="' . esc_url( get_term_link( $term ) ) . '">' . esc_html( $term->name ) . '</a>'
				: esc_html( $term->name );
		}
	}
	if ( $names ) {
		echo '<div class="perfectpixel-loop-brand" style="font-size:.8em;text-transform:uppercase;letter-spacing:.05em;opacity:.8">' . implode( ', ', $names ) . '</div>';
	}
}
